square_matrix_mul_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

// Tile size (should be a multiple of 16 for optimal performance)
#define TILE_SIZE 32

__global__ void square_matrix_mul_kernel(const float* A, const float* B, float* C, int N) {
    // Block row and column
    int blockRow = blockIdx.y;
    int blockCol = blockIdx.x;

    // Thread row and column within the tile
    int threadRow = threadIdx.y;
    int threadCol = threadIdx.x;

    // Row and column of the C element calculated by this thread
    int row = blockRow * TILE_SIZE + threadRow;
    int col = blockCol * TILE_SIZE + threadCol;

    // Shared memory for tiles of A and B
    __shared__ float shA[TILE_SIZE][TILE_SIZE];
    __shared__ float shB[TILE_SIZE][TILE_SIZE];

    float sum = 0.0f;

    // Iterate over tiles
    int numTiles = (N + TILE_SIZE - 1) / TILE_SIZE;
    for (int t = 0; t < numTiles; ++t) {
        // Load tile of A into shared memory
        int aRow = row;
        int aCol = t * TILE_SIZE + threadCol;
        if (aRow < N && aCol < N) {
            shA[threadRow][threadCol] = A[aRow * N + aCol];
        } else {
            shA[threadRow][threadCol] = 0.0f; // Pad with zeros if out of bounds
        }

        // Load tile of B into shared memory
        int bRow = t * TILE_SIZE + threadRow;
        int bCol = col;
        if (bRow < N && bCol < N) {
            shB[threadRow][threadCol] = B[bRow * N + bCol];
