#include <cuda_runtime.h>

// Tile size (should be a multiple of 16 for optimal performance)
#define TILE_SIZE 32

__global__ void square_matrix_mul_kernel(const float* A, const float* B, float* C, int N) {
    // Block row and column
    int blockRow = blockIdx.y;
    int blockCol = blockIdx.x;

    // Thread row and column within the tile
    int threadRow = threadIdx.y;
    int threadCol = threadIdx.x;

    // Row and column of the C element calculated by this thread
    int row = blockRow * TILE_SIZE + threadRow;
    int col = blockCol * TILE_SIZE + threadCol;

    // Shared memory for tiles of A and B
    // +1 to avoid bank conflicts for each row of the shared memory array
    __shared__ float shA[TILE_SIZE][TILE_SIZE + 1];
    __shared__ float shB_T[TILE_SIZE][TILE_SIZE + 1]; // Transposed B

    float sum = 0.0f;

    // Iterate over tiles
    int numTiles = (N + TILE_SIZE - 1) / TILE_SIZE;
    for (int t = 0; t < numTiles; ++t) {
        // Load tile of A into shared memory
        int aRow = row;
        int aCol = t * TILE_SIZE + threadCol;
        shA[threadRow][threadCol] = (aRow < N && aCol < N) ? A[aRow * N + aCol] : 0.0f;

        // Load tile of B (transposed) into shared memory
        // Original B index: B[bRow * N + bCol]
        // Transposed B index: shB_T[bCol_in_tile][bRow_in_tile]
        int bRow = t * TILE_SIZE + threadRow;
        int bCol = col;
        shB_T[threadCol][threadRow] = (bRow < N && bCol < N) ? B[bRow * N + bCol] : 0.0f;

        __syncthreads();

        // Perform matrix multiplication on the shared memory tiles
        // C[row][col] = sum(A[row][k] * B[k][col])
        // With transposed B: B[k][col] is equivalent to B_T[col][k]
        if (row < N && col < N) {
            for (int k = 0; k < TILE_SIZE; ++k) {
                sum += shA[threadRow][k] * shB_T[threadCol][k];
            }
        }
        __syncthreads();
    }

    if (row < N && col < N) {
        C[row * N + col] = sum;
    }
}

torch::Tensor square_matrix_mul_cuda(torch::Tensor A, torch::Tensor B) {
    int N = A.size(0);
    auto C = torch::zeros_like(A);

    dim3 dimBlock(TILE_SIZE, TILE_SIZE);
    dim3 dimGrid((N + TILE_SIZE - 1) / TILE_SIZE, (N + TILE_SIZE - 1) / TILE_SIZE);

    square_matrix_mul_kernel<<<dimGrid, dimBlock>>>(
        A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), N
    );

    return C;
}
